"""Learned event re-scorer: decide per detected region whether to repair it.

Each region the neural detector emits is described by a small feature vector

* local shape   -- logit peak/mean, region length, curvature contrast,
                   energy of the 2-30 ms tail vs the 30 ms before, spectral
                   change (6 bands) of the event window vs the window before,
                   local and long-term level;
* stereo        -- the other channel's logit and region overlap within 1 ms,
                   L/R correlation of the event, side/mid energy change;
* rhythm        -- periodicity of an onset-flux envelope (autocorrelation over
                   0.2-1.25 s lags) and whether the neighbouring detections
                   (both channels) sit on a regular grid through this event,
                   within a context window [t - past, t + future].

and a tiny MLP (trained on longform TRAIN: VinylStudio repairs + real clicks
injected at random times = repair; VinylStudio "detected only" + unlabelled
detections = leave) outputs p(repair).  Regions with p < ``tau`` are spared.

Rotation-periodic defects: lags within +-4 % of the 78 RPM rotation period
(0.769 s) are excluded from both periodicity measures, and 33 1/3 / 45 RPM
periods (1.8 s / 1.333 s) are outside the 0.2-1.25 s beat range.  The grid
score also needs a neighbour at exactly one period (k = +-1), so a click
that recurs every revolution cannot pose as a sub-multiple "beat"
(e.g. 0.9 s or 0.6 s for 1.8 s).

Streaming: everything is either per-region (bounded windows <= 1440 samples
after onset) or a running 10 ms onset-flux envelope plus a ring of recent
detection times, so the Rust port needs ``future`` seconds of extra delay
and O(context) memory.
"""

from __future__ import annotations

import math

import numpy as np

from pressing_tools import classical

SR = 48000
HOP = 480                               # onset-envelope hop (10 ms)
ROT_LAGS = (60 / 78,)                   # rotation periods inside the beat range (s)
ROT_TOL = 0.04
BEAT_MIN, BEAT_MAX = 0.2, 1.25          # beat-period search range (s)
TAIL_LO, TAIL_HI = 96, 1440             # 2..30 ms after onset
BANDS = (0, 500, 1500, 3000, 6000, 12000, 24001)
NFFT = 1024


# MARK: - Feature helpers


def _csum(v: np.ndarray) -> np.ndarray:
    return np.r_[0.0, np.cumsum(v)]


def _mean(cs: np.ndarray, a: int, b: int) -> float:
    n = len(cs) - 1
    a, b = max(0, a), min(n, b)
    if b <= a:
        return 0.0
    return (cs[b] - cs[a]) / (b - a)


def _db(v: float) -> float:
    return 10.0 * math.log10(v + 1e-14)


def _beat_lags(hop_s: float) -> np.ndarray:
    lags = np.arange(int(BEAT_MIN / hop_s), int(BEAT_MAX / hop_s) + 1)
    ok = np.ones(len(lags), bool)
    for r in ROT_LAGS:
        ok &= np.abs(lags * hop_s / r - 1) > ROT_TOL
    return lags[ok]


_WIN = np.hanning(NFFT)
_FREQ = np.fft.rfftfreq(NFFT, 1 / SR)
_BAND_IDX = [(np.searchsorted(_FREQ, lo), np.searchsorted(_FREQ, hi)) for lo, hi in zip(BANDS[:-1], BANDS[1:])]


def _bands(seg: np.ndarray) -> tuple[np.ndarray, float, float]:
    if len(seg) < NFFT:
        seg = np.pad(seg, (0, NFFT - len(seg)))
    p = np.abs(np.fft.rfft(seg * _WIN)) ** 2 + 1e-14
    be = np.array([p[a:b].sum() for a, b in _BAND_IDX])
    cent = float((p * _FREQ).sum() / p.sum())
    flat = float(np.exp(np.mean(np.log(p[1:]))) / np.mean(p[1:]))
    return 10 * np.log10(be + 1e-14), math.log(cent + 1.0), math.log(flat + 1e-9)


# MARK: - Context (rhythm) features


def onset_envelope(x2: np.ndarray) -> np.ndarray:
    """10 ms log-energy flux of the differentiated mid signal."""
    d = np.diff((x2[0] + x2[1]) * 0.5, prepend=0.0)
    nf = len(d) // HOP
    e = (d[:nf * HOP].reshape(nf, HOP) ** 2).sum(1)
    le = 10 * np.log10(e + 1e-10)
    return np.maximum(0.0, np.diff(le, prepend=le[:1]))


def rhythm_env(env: np.ndarray, f: int, wp: int, wf: int, lags: np.ndarray) -> tuple[float, float, float]:
    """Max normalised autocorrelation over beat lags in [f-wp, f+wf], the
    flux at f vs the window's 90th percentile, and the mean flux one best-lag
    away from f (is this event on the beat grid of the music?)."""
    lo, hi = max(0, f - wp), min(len(env), f + wf + 1)
    w = env[lo:hi]
    if len(w) < lags[0] * 3:
        return 0.0, 0.0, 0.0
    v = w - w.mean()
    den = float(v @ v) + 1e-9
    usable = lags[lags < len(v) // 2]
    if not len(usable):
        return 0.0, 0.0, 0.0
    ac = np.array([float(v[:-l] @ v[l:]) for l in usable]) / den
    i = int(np.argmax(ac))
    L = int(usable[i])
    p90 = float(np.percentile(w, 90)) + 1e-3
    here = float(env[max(0, f - 1):f + 2].max())
    nb = [env[max(0, g - 1):g + 2].max() for g in (f - L, f + L) if lo <= g - 1 and g + 2 <= hi]
    onb = float(np.mean(nb)) / p90 if nb else 0.0
    return float(ac[i]), here / p90, onb


def grid_score(t: float, nb: np.ndarray, periods: np.ndarray, past: float, fut: float,
               tol: float = 0.012) -> tuple[float, float]:
    """Best count of neighbouring detections at t + k P (k = +-1..+-4, inside
    the context window), requiring a hit at k = +-1; also returns the best
    fraction of available grid positions hit."""
    if len(nb) == 0:
        return 0.0, 0.0
    best, bestf = 0.0, 0.0
    ks = np.array([-4, -3, -2, -1, 1, 2, 3, 4], float)
    pos = t + periods[:, None] * ks[None, :]                       # (P, 8)
    avail = (pos >= t - past) & (pos <= t + fut)
    j = np.searchsorted(nb, pos)
    d1 = np.abs(nb[np.clip(j, 0, len(nb) - 1)] - pos)
    d0 = np.abs(nb[np.clip(j - 1, 0, len(nb) - 1)] - pos)
    hit = (np.minimum(d0, d1) <= tol) & avail
    need = hit[:, 3] | hit[:, 4]
    cnt = np.where(need, hit.sum(1), 0)
    na = np.maximum(avail.sum(1), 1)
    best = float(cnt.max())
    bestf = float((cnt / na).max())
    return best, bestf


# MARK: - Region features


FEATURES = [
    "peak", "mean", "len", "contrast", "tail_d", "tail_x", "post_d", "spike",
    "lvl", "lvl_long", "o_logit", "o_region", "corr", "side",
    "b0", "b1", "b2", "b3", "b4", "b5", "cent", "flat",
    "acf", "flux_here", "flux_onbeat", "density", "grid", "grid_frac", "grid_ctl",
    "pre_rise", "cl_n", "cl_tail", "flux_recent",
]
CL_PRE, CL_POST = 2400, 480        # cluster window around an onset (50 ms before, 10 ms after)
CTL_OFFSETS = (-0.09, -0.05, 0.05, 0.09)    # off-grid control positions (s)


def region_features(x2: np.ndarray, s2: np.ndarray, regions, sr: int = SR,
                    past: float = 2.0, fut: float = 2.0) -> list[np.ndarray]:
    N = x2.shape[1]
    d2 = np.diff(x2, axis=1, prepend=0.0)
    cx = [_csum(x2[c] ** 2) for c in range(2)]
    cd = [_csum(d2[c] ** 2) for c in range(2)]
    mid, side = (d2[0] + d2[1]) * 0.5, (d2[0] - d2[1]) * 0.5
    cm, cs_ = _csum(mid ** 2), _csum(side ** 2)
    env = onset_envelope(x2)
    hop_s = HOP / sr
    lags = _beat_lags(hop_s)
    periods = np.arange(BEAT_MIN, BEAT_MAX, 0.005)
    keep_p = np.ones(len(periods), bool)
    for r in ROT_LAGS:
        keep_p &= np.abs(periods / r - 1) > ROT_TOL
    periods = periods[keep_p]
    wp, wf = int(round(past / hop_s)), int(round(fut / hop_s))
    # detection onsets (both channels, merged within 2 ms), in seconds
    on = np.sort(np.array([a for c in range(2) for a, _ in regions[c]], float))
    if len(on):
        on = on[np.r_[True, np.diff(on) > 96]]
    ts = on / sr
    other_mask = []
    for c in range(2):
        m = np.zeros(N + 1, np.int32)
        for a, b in regions[c]:
            m[a] += 1
            m[b] -= 1
        other_mask.append(_csum(np.cumsum(m[:N]) > 0))
    # tail ratio of every region (both channels) for cluster features: a clap
    # is several bursts within ~30 ms, and later bursts lack their own tail
    allr = sorted((int(a), c, _db(_mean(cd[c], a + TAIL_LO, a + TAIL_HI)) - _db(_mean(cd[c], a - 1440, a)))
                  for c in range(2) for a, _ in regions[c])
    all_a = np.array([r[0] for r in allr], np.int64)
    all_t = np.array([r[2] for r in allr])
    out = []
    rh_cache: dict[int, tuple] = {}
    for c in range(2):
        x, d, s, so = x2[c], d2[c], s2[c], s2[1 - c]
        rows = []
        for a, b in regions[c]:
            a, b = int(a), int(b)
            f = []
            seg = s[a:b]
            f += [float(seg.max()), float(seg.mean()), math.log(b - a)]
            f.append(math.log(classical.contrast(x, a, b) + 1e-6))
            pre_d = _mean(cd[c], a - 1440, a)
            f.append(_db(_mean(cd[c], a + TAIL_LO, a + TAIL_HI)) - _db(pre_d))
            f.append(_db(_mean(cx[c], a + TAIL_LO, a + TAIL_HI)) - _db(_mean(cx[c], a - 1440, a)))
            f.append(_db(_mean(cd[c], b + 48, b + 480)) - _db(_mean(cd[c], a - 480, a)))
            f.append(_db(float(np.max(d[a:b] ** 2))) - _db(pre_d))
            f.append(_db(_mean(cx[c], a - 4800, a)))
            f.append(_db(_mean(cx[c], a - sr, a)))
            lo, hi = max(0, a - 48), min(N, b + 48)
            f.append(float(so[lo:hi].max()))
            oc = other_mask[1 - c]
            f.append(1.0 if oc[hi] - oc[lo] > 0 else 0.0)
            u, v = d2[0, max(0, a - 16):b + 16], d2[1, max(0, a - 16):b + 16]
            f.append(float(u @ v / (math.sqrt((u @ u) * (v @ v)) + 1e-14)))
            f.append((_db(_mean(cs_, a, b)) - _db(_mean(cm, a, b)))
                     - (_db(_mean(cs_, a - 1440, a)) - _db(_mean(cm, a - 1440, a))))
            ev = x[max(0, a - 32):a - 32 + NFFT]
            pr = x[max(0, a - 32 - NFFT):max(0, a - 32)]
            be, cent, flat = _bands(ev)
            bp, _, _ = _bands(pr)
            f += list(be - bp) + [cent, flat]
            fr = a // HOP
            if fr not in rh_cache:
                rh_cache[fr] = rhythm_env(env, fr, wp, wf, lags)
            f += list(rh_cache[fr])
            t = a / sr
            lo_t, hi_t = t - past, t + fut
            i0, i1 = np.searchsorted(ts, lo_t), np.searchsorted(ts, hi_t, side="right")
            nb = ts[i0:i1]
            nb = nb[np.abs(nb - t) > 0.002]
            span = max(1e-3, min(hi_t, N / sr) - max(lo_t, 0.0))
            f.append(math.log1p(len(nb) / span))
            g = grid_score(t, nb, periods, past, fut)
            # same score at off-grid control times: on a beat grid the event
            # itself scores higher; among random crackle all positions score alike
            ctl = [grid_score(t + o, nb, periods, past + o, fut - o)[0] for o in CTL_OFFSETS]
            f += [g[0], g[1], g[0] - float(np.mean(ctl))]
            f.append(_db(_mean(cd[c], a - 1440, a)) - _db(_mean(cd[c], a - 6240, a - 1440)))
            i0, i1 = np.searchsorted(all_a, a - CL_PRE), np.searchsorted(all_a, a + CL_POST, side="right")
            f.append(math.log1p(i1 - i0 - 1))
            f.append(float(all_t[i0:i1].max()) if i1 > i0 else 0.0)
            f.append(float(env[max(0, fr - 5):fr + 1].max()) if len(env) else 0.0)
            rows.append(f)
        out.append(np.array(rows, np.float64).reshape(-1, len(FEATURES)))
    return out


# MARK: - Model


def mlp_forward(X: np.ndarray, W: dict) -> np.ndarray:
    """Standardise -> [Linear -> tanh]* -> Linear -> logit."""
    if "cols" in W:
        X = X[:, W["cols"]]
    h = (X - np.asarray(W["mu"])) / np.asarray(W["sd"])
    layers = W["layers"]
    for i, (w, bias) in enumerate(layers):
        h = h @ np.asarray(w).T + np.asarray(bias)
        if i < len(layers) - 1:
            h = np.tanh(h)
    return h[:, 0]


class _Base:
    name = "rescorer"
    past = 2.0
    fut = 2.0
    variant = "long"

    def __init__(self, tau: float | None = None, strength: float | None = None):
        W = WEIGHTS.get(self.variant)
        if W is None:
            raise RuntimeError(f"no trained weights for variant {self.variant!r}")
        self.W = W
        # strength 0..1: 0 = never protect, 1 = protect aggressively.  The
        # default strength corresponds to the tau tuned on longform val.
        if tau is None:
            tau = W["tau"] if strength is None else strength_to_tau(strength, W)
        self.tau = tau
        # future audio needed beyond the base detector: the per-region
        # windows reach 30 ms past the onset (~20 ms past the detector's own
        # 10.7 ms), plus the rhythm context.
        self.lookahead_s = max(TAIL_HI / SR, self.fut + TAIL_HI / SR)

    def logits(self, x2, s2, regions, sr):
        F = region_features(x2, s2, regions, sr, self.past, self.fut)
        return [mlp_forward(f, self.W) if len(f) else np.zeros(0) for f in F]

    def keep(self, x2, s2, regions, sr):
        return [[bool(v >= self.tau) for v in z] for z in self.logits(x2, s2, regions, sr)]


def strength_to_tau(strength: float, W: dict) -> float:
    """Linear map of a 0..1 user strength onto the logit threshold:
    0 -> W['tau_off'] (protects ~nothing), 0.5 -> tuned default, 1 -> W['tau_max']."""
    s = min(1.0, max(0.0, strength))
    if s <= 0.5:
        return W["tau_off"] + (W["tau"] - W["tau_off"]) * s / 0.5
    return W["tau"] + (W["tau_max"] - W["tau"]) * (s - 0.5) / 0.5


class Protector(_Base):
    """Long look-ahead (high-latency mode): rhythm context t-2 s .. t+2 s."""
    variant = "long"
    past, fut = 2.0, 2.0


class ProtectorShort(_Base):
    """Low-latency mode: rhythm context from the past 4 s only."""
    variant = "short"
    past, fut = 4.0, 0.0


# MARK: - Weights (generated by the training script; see module docstring)

